// NULL-tolerant scan buffer for categoryScanMapperNullable:
// on a LEFT JOIN miss every column comes back NULL, so each field uses the
// nullable version of the column type even when the column itself is NOT NULL.
type categoryPreloadBuf struct {
	ID               null.Val[uuid.UUID]
	Name             null.Val[string]
	IsGroup          null.Val[bool]
	ParentID         null.Val[uuid.UUID]
	ShouldBeBudgeted null.Val[bool]
	IsDisabled       null.Val[bool]
	CategoryType     null.Val[int16]
	CreatedAt        null.Val[time.Time]
}

// categoryScanMapperNullable maps the preloaded category
// columns (prefixed with the runtime join alias) without reflection, while
// keeping the LEFT JOIN semantics of the reflection-based mapper: a row whose
// prefixed columns are all NULL yields nil (no child), and NULL values never
// error, they just leave the zero value in the field.
func categoryScanMapperNullable(prefix string) scan.Mapper[*Category] {
	return func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*Category, error)) {
		// resolve the column names once per query, not per row
		type target struct {
			idx int
			dst func(b *categoryPreloadBuf) any
		}
		targets := make([]target, 0, 8)
		for i, col := range cols {
			name, ok := strings.CutPrefix(col, prefix)
			if !ok {
				continue
			}
			switch name {
			case "id":
				targets = append(targets, target{i, func(b *categoryPreloadBuf) any { return &b.ID }})
			case "name":
				targets = append(targets, target{i, func(b *categoryPreloadBuf) any { return &b.Name }})
			case "is_group":
				targets = append(targets, target{i, func(b *categoryPreloadBuf) any { return &b.IsGroup }})
			case "parent_id":
				targets = append(targets, target{i, func(b *categoryPreloadBuf) any { return &b.ParentID }})
			case "should_be_budgeted":
				targets = append(targets, target{i, func(b *categoryPreloadBuf) any { return &b.ShouldBeBudgeted }})
			case "is_disabled":
				targets = append(targets, target{i, func(b *categoryPreloadBuf) any { return &b.IsDisabled }})
			case "category_type":
				targets = append(targets, target{i, func(b *categoryPreloadBuf) any { return &b.CategoryType }})
			case "created_at":
				targets = append(targets, target{i, func(b *categoryPreloadBuf) any { return &b.CreatedAt }})
			}
		}

		// One scratch buffer reused for every row: before -> scan -> after runs
		// synchronously per row, the scheduled columns are fully overwritten each
		// row, and unselected columns stay zero, so a single buffer preserves the
		// per-row NULL semantics without allocating a buffer per parent row. The
		// returned child (o below) is always freshly allocated, so buf never
		// escapes past the after func.
		buf := new(categoryPreloadBuf)
		return func(row *scan.Row) (any, error) {
				for _, t := range targets {
					row.ScheduleScanByIndex(t.idx, t.dst(buf))
				}
				return buf, nil
			}, func(link any) (*Category, error) {
				buf := link.(*categoryPreloadBuf)

				// Same rule as the reflection mapper's row validator: the child
				// exists only if at least one of its columns is not NULL. Columns
				// not selected by the query are never scanned and stay invalid,
				// so this check also matches when only a subset is selected.
				if !(buf.ID.IsValue()) &&
					!(buf.Name.IsValue()) &&
					!(buf.IsGroup.IsValue()) &&
					!(buf.ParentID.IsValue()) &&
					!(buf.ShouldBeBudgeted.IsValue()) &&
					!(buf.IsDisabled.IsValue()) &&
					!(buf.CategoryType.IsValue()) &&
					!(buf.CreatedAt.IsValue()) {
					return nil, nil
				}

				o := new(Category)
				if buf.ID.IsValue() {
					o.ID = buf.ID.MustGet()
				}
				if buf.Name.IsValue() {
					o.Name = buf.Name.MustGet()
				}
				if buf.IsGroup.IsValue() {
					o.IsGroup = buf.IsGroup.MustGet()
				}
				o.ParentID = buf.ParentID
				if buf.ShouldBeBudgeted.IsValue() {
					o.ShouldBeBudgeted = buf.ShouldBeBudgeted.MustGet()
				}
				if buf.IsDisabled.IsValue() {
					o.IsDisabled = buf.IsDisabled.MustGet()
				}
				if buf.CategoryType.IsValue() {
					o.CategoryType = buf.CategoryType.MustGet()
				}
				if buf.CreatedAt.IsValue() {
					o.CreatedAt = buf.CreatedAt.MustGet()
				}
				return o, nil
			}
	}
}

func (o *Category) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "Budgets":
		rels, ok := retrieved.(BudgetSlice)
		if !ok {
			return fmt.Errorf("category cannot load %T as %q", retrieved, name)
		}

		o.R.Budgets = rels
		o.R.Loaded.Budgets = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Category = o
				rel.R.Loaded.Category = true
			}
		}
		return nil
	case "Parent":
		rel, ok := retrieved.(*Category)
		if !ok {
			return fmt.Errorf("category cannot load %T as %q", retrieved, name)
		}

		o.R.Parent = rel
		o.R.Loaded.Parent = true

		if rel != nil {
			rel.R.ReverseParents = CategorySlice{o}
		}
		return nil
	case "ReverseParents":
		rels, ok := retrieved.(CategorySlice)
		if !ok {
			return fmt.Errorf("category cannot load %T as %q", retrieved, name)
		}

		o.R.ReverseParents = rels
		o.R.Loaded.ReverseParents = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Parent = o
				rel.R.Loaded.Parent = true
			}
		}
		return nil
	case "Transactions":
		rels, ok := retrieved.(TransactionSlice)
		if !ok {
			return fmt.Errorf("category cannot load %T as %q", retrieved, name)
		}

		o.R.Transactions = rels
		o.R.Loaded.Transactions = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Category = o
				rel.R.Loaded.Category = true
			}
		}
		return nil
	default:
		return fmt.Errorf("category has no relationship %q", name)
	}
}

type categoryPreloader struct {
	Parent func(...psql.PreloadOption) psql.Preloader
}

func buildCategoryPreloader() categoryPreloader {
	return categoryPreloader{
		Parent: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*Category, CategorySlice](psql.PreloadRel{
				Name: "Parent",
				Sides: []psql.PreloadSide{
					{
						From:        Categories,
						To:          Categories,
						FromColumns: []string{"parent_id"},
						ToColumns:   []string{"id"},
					},
				},
			}, Categories.Columns.Names(), categoryScanMapperNullable, opts...)
		},
	}
}

type categoryThenLoader[Q orm.Loadable] struct {
	Budgets        func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	Parent         func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	ReverseParents func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	Transactions   func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildCategoryThenLoader[Q orm.Loadable]() categoryThenLoader[Q] {
	type BudgetsLoadInterface interface {
		LoadBudgets(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type ParentLoadInterface interface {
		LoadParent(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type ReverseParentsLoadInterface interface {
		LoadReverseParents(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type TransactionsLoadInterface interface {
		LoadTransactions(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return categoryThenLoader[Q]{
		Budgets: thenLoadBuilder[Q](
			"Budgets",
			func(ctx context.Context, exec bob.Executor, retrieved BudgetsLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadBudgets(ctx, exec, mods...)
			},
		),
		Parent: thenLoadBuilder[Q](
			"Parent",
			func(ctx context.Context, exec bob.Executor, retrieved ParentLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadParent(ctx, exec, mods...)
			},
		),
		ReverseParents: thenLoadBuilder[Q](
			"ReverseParents",
			func(ctx context.Context, exec bob.Executor, retrieved ReverseParentsLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadReverseParents(ctx, exec, mods...)
			},
		),
		Transactions: thenLoadBuilder[Q](
			"Transactions",
			func(ctx context.Context, exec bob.Executor, retrieved TransactionsLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadTransactions(ctx, exec, mods...)
			},
		),
	}
}

// LoadBudgets loads the category's Budgets into the .R struct
func (o *Category) LoadBudgets(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Budgets = nil
	o.R.Loaded.Budgets = false

	related, err := o.Budgets(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, rel := range related {
		rel.R.Category = o
		rel.R.Loaded.Category = true
	}

	o.R.Budgets = related
	o.R.Loaded.Budgets = true
	return nil
}

// LoadBudgets loads the category's Budgets into the .R struct
func (os CategorySlice) LoadBudgets(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	budgets, err := os.Budgets(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Budgets = nil
		o.R.Loaded.Budgets = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	categoryByKey := make(map[uuid.UUID][]*Category, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		categoryByKey[o.ID] = append(categoryByKey[o.ID], o)
	}

	for _, rel := range budgets {

		owners, ok := categoryByKey[rel.CategoryID]
		if !ok {
			continue
		}

		for _, o := range owners {

			rel.R.Category = o
			rel.R.Loaded.Category = true

			o.R.Budgets = append(o.R.Budgets, rel)

		}
	}

	return nil
}

// LoadParent loads the category's Parent into the .R struct
func (o *Category) LoadParent(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Parent = nil
	o.R.Loaded.Parent = false

	related, err := o.Parent(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.ReverseParents = CategorySlice{o}

	o.R.Parent = related
	o.R.Loaded.Parent = true
	return nil
}

// LoadParent loads the category's Parent into the .R struct
func (os CategorySlice) LoadParent(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	categories, err := os.Parent(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Parent = nil
		o.R.Loaded.Parent = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	categoryByKey := make(map[uuid.UUID][]*Category, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		// NULL never matches any row in SQL, so don't add it to the map
		if !o.ParentID.IsValue() {
			continue
		}

		categoryByKey[o.ParentID.MustGet()] = append(categoryByKey[o.ParentID.MustGet()], o)
	}

	for _, rel := range categories {

		owners, ok := categoryByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.Parent != nil {
				continue
			}

			rel.R.ReverseParents = append(rel.R.ReverseParents, o)

			o.R.Parent = rel

		}
	}

	return nil
}

