// categoryC is where relationship counts are stored.
type categoryC struct {
	Budgets        *int64
	ReverseParents *int64
	Transactions   *int64
}

// PreloadCount sets a count in the C struct by name
func (o *Category) PreloadCount(name string, count int64) error {
	if o == nil {
		return nil
	}

	switch name {
	case "Budgets":
		o.C.Budgets = &count
	case "ReverseParents":
		o.C.ReverseParents = &count
	case "Transactions":
		o.C.Transactions = &count
	}
	return nil
}

type categoryCountPreloader struct {
	Budgets        func(...bob.Mod[*dialect.SelectQuery]) psql.Preloader
	ReverseParents func(...bob.Mod[*dialect.SelectQuery]) psql.Preloader
	Transactions   func(...bob.Mod[*dialect.SelectQuery]) psql.Preloader
}

func buildCategoryCountPreloader() categoryCountPreloader {
	return categoryCountPreloader{
		Budgets: func(mods ...bob.Mod[*dialect.SelectQuery]) psql.Preloader {
			return countPreloader[*Category]("Budgets", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = Categories.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(psql.Raw("count(*)")),

					sm.From(Budgets.NameAsExpr()),
					sm.Where(psql.Quote(Budgets.Alias(), "category_id").EQ(psql.Quote(parent, "id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return psql.Group(psql.Select(subqueryMods...).Expression)
			})
		},
		ReverseParents: func(mods ...bob.Mod[*dialect.SelectQuery]) psql.Preloader {
			return countPreloader[*Category]("ReverseParents", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = Categories.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(psql.Raw("count(*)")),

					sm.From(Categories.NameAsExpr()),
					sm.Where(psql.Quote(Categories.Alias(), "parent_id").EQ(psql.Quote(parent, "id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return psql.Group(psql.Select(subqueryMods...).Expression)
			})
		},
		Transactions: func(mods ...bob.Mod[*dialect.SelectQuery]) psql.Preloader {
			return countPreloader[*Category]("Transactions", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = Categories.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(psql.Raw("count(*)")),

					sm.From(Transactions.NameAsExpr()),
					sm.Where(psql.Quote(Transactions.Alias(), "category_id").EQ(psql.Quote(parent, "id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return psql.Group(psql.Select(subqueryMods...).Expression)
			})
		},
	}
}

type categoryCountThenLoader[Q orm.Loadable] struct {
	Budgets        func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	ReverseParents func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	Transactions   func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildCategoryCountThenLoader[Q orm.Loadable]() categoryCountThenLoader[Q] {
	type BudgetsCountInterface interface {
		LoadCountBudgets(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type ReverseParentsCountInterface interface {
		LoadCountReverseParents(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type TransactionsCountInterface interface {
		LoadCountTransactions(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return categoryCountThenLoader[Q]{
		Budgets: countThenLoadBuilder[Q](
			"Budgets",
			func(ctx context.Context, exec bob.Executor, retrieved BudgetsCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountBudgets(ctx, exec, mods...)
			},
		),
		ReverseParents: countThenLoadBuilder[Q](
			"ReverseParents",
			func(ctx context.Context, exec bob.Executor, retrieved ReverseParentsCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountReverseParents(ctx, exec, mods...)
			},
		),
		Transactions: countThenLoadBuilder[Q](
			"Transactions",
			func(ctx context.Context, exec bob.Executor, retrieved TransactionsCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountTransactions(ctx, exec, mods...)
			},
		),
	}
}

// LoadCountBudgets loads the count of Budgets into the C struct
func (o *Category) LoadCountBudgets(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	count, err := o.Budgets(mods...).Count(ctx, exec)
	if err != nil {
		return err
	}

	o.C.Budgets = &count
	return nil
}

// LoadCountBudgets loads the count of Budgets for a slice in a single batch query
func (os CategorySlice) LoadCountBudgets(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	// Build the IN arg expression from parent PKs

	pkID := make(pgtypes.Array[uuid.UUID], 0, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}
		pkID = append(pkID, o.ID)
	}
	PKArgExpr := psql.Any(psql.Cast(psql.Arg(pkID), "uuid[]"))

	// countResult holds one scanned row from the batch count query.
	// FK columns are aliased to the parent PK column names for direct map lookup.
	type countResult struct {
		ID    uuid.UUID
		Count int64
	}

	batchMods := []bob.Mod[*dialect.SelectQuery]{
		// SELECT fk AS parent_pk, count(*)
		sm.Columns(
			Budgets.Columns.CategoryID.As("id"),
			psql.Raw("count(*) as count"),
		),
		// Single-hop: FROM related table directly
		sm.From(Budgets.NameAsExpr()),

		// WHERE fk IN (parent PKs) — psql single-column FK uses `= ANY(array)` (see PKArgExpr above)
		sm.Where(Budgets.Columns.CategoryID.EQ(PKArgExpr)),
		// GROUP BY fk columns
		sm.GroupBy(Budgets.Columns.CategoryID),
	}
	batchMods = append(batchMods, mods...)

	results, err := bob.All(ctx, exec,
		psql.Select(batchMods...),
		scan.StructMapper[countResult](),
	)
	if err != nil {
		return err
	}

	// Single-column FK: direct map lookup
	countMap := make(map[uuid.UUID]int64, len(results))
	for _, r := range results {
		countMap[r.ID] = r.Count
	}
	for _, o := range os {
		if o == nil {
			continue
		}
		count := countMap[o.ID]
		o.C.Budgets = &count
	}

	return nil
}

